+namespace sv_0702396a9f05425daa685bf76b9018b2.Services;
+
+/// <summary>
+/// Polls for low-stock alerts on a 10-second interval.
+/// Scoped per circuit so each user gets independent counts.
+/// </summary>
+public sealed class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private PeriodicTimer? _timer;
+    private CancellationTokenSource? _cts;
+    private int _subscriberCount;
+
+    public int CurrentLowStockCount { get; private set; }
+
+    /// <summary>
+    /// Raised whenever a new alert count is fetched.
+    /// All subscribed components should re-render.
+    /// </summary>
+    public event Func<Task>? OnAlertCountChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+    }
+
+    /// <summary>Simulates a database query. Returns a random number 0–15.</summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        return Task.FromResult(Random.Shared.Next(0, 16));
+    }
+
+    /// <summary>
+    /// Call from OnInitializedAsync of any component that wants polling.
+    /// Ref-counted: polling starts on first subscriber, stops on last unsubscribe.
+    /// </summary>
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_subscriberCount == 1)
+            BeginPollingLoop();
+    }
+
+    /// <summary>Call from Dispose of the subscribing component.</summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+            CancelPollingLoop();
+    }
+
+    private void BeginPollingLoop()
+    {
+        _cts = new CancellationTokenSource();
+        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+        _ = PollLoopAsync(_cts.Token);
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        // Fetch immediately on start, then every 10 s.
+        await FetchAndNotifyAsync();
+
+        try
+        {
+            while (await _timer!.WaitForNextTickAsync(ct))
+            {
+                await FetchAndNotifyAsync();
+            }
+        }
+        catch (OperationCanceledException) { /* expected on stop */ }
+    }
+
+    private async Task FetchAndNotifyAsync()
+    {
+        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+        if (OnAlertCountChanged is not null)
+            await OnAlertCountChanged.Invoke();
+    }
+
+    private void CancelPollingLoop()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+        _timer?.Dispose();
+        _timer = null;
+    }
+
+    public void Dispose()
+    {
+        CancelPollingLoop();
+    }
+}
